import{z as l,x as B,o as n,c as d,q as r,j as A,D as e,d as E,s as o,S as s,b as t}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"条件概率与贝叶斯","description":"","frontmatter":{"title":"条件概率与贝叶斯","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/conditional-bayes.md","filePath":"cs/conditional-bayes.md","lastUpdated":1791063341000}'),p={name:"cs/conditional-bayes.md"};function P(c,a,m,h,_,C){const i=B("Mermaid");return n(),d("div",null,[a[2]||(a[2]=r('<h1 id="条件概率与贝叶斯" tabindex="-1">条件概率与贝叶斯 <a class="header-anchor" href="#条件概率与贝叶斯" aria-label="Permalink to &quot;条件概率与贝叶斯&quot;">​</a></h1><div class="epigraph"><p>看见 $B$ 之后 $A$ 的权重，是把质量限制在 $B$ 上再归一化；贝叶斯把「果的似然」翻成「因的后验」。</p><footer>—— 据 Rosen, Discrete Mathematics and Its Applications；Shannon, 1948 整理</footer></div><p>上一课<a href="/cs/expectation-linearity">期望与线性性</a>钉死了指示变量与无独立的求和。<a href="/cs/discrete-probability">离散概率</a>已定义 \\(P(A|B)=P(A\\cap B)/P(B)\\)，并说贝叶斯是改求和次序。本课不重写 \\(|\\Omega|\\)，也不从因果哲学另起。缺口是：定义还不是计算步骤。误码、检验、后课信道，要把 \\(P(\\text{发送}| \\text{接收})\\) 从 \\(P(\\text{接收}| \\text{发送})\\) 翻出来，并避免忽略先验。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>全概率：划分 \\(\\{B_i\\}\\) 时 \\(P(A)=\\sum_i P(A|B_i)P(B_i)\\)。<span class="marginnote">「条件概率」翻译成白话：把整个样本空间缩到 \\(B\\) 发生的那一小块，再看 \\(A\\) 在里面占多大比例——好比骰子掷出了偶数（6 种里剩 3 种），再问这 3 种里大于 4 的占几成：答案从 2/6 变成 1/3，因为「世界」变小了。</span>贝叶斯：</p> \\[P(B_j|A)=\\frac{P(A|B_j)P(B_j)}{\\sum_i P(A|B_i)P(B_i)}. \\]<p>缺口因此不是新的线性性，而是<strong>反转条件方向</strong>，以及分母里必须把所有假设加总。先验 \\(P(B_j)\\) 很小则即便似然大，后验也可以小——基础比率。熵课的 \\(H(X|Y)\\) 现在是：给定 \\(Y\\) 之后，在条件分布上再算上一课那种期望；互信息是平均少了多少不确定。本课不把贝叶斯网展开。</p><p>信息与离散主干到此结束。下一课改做<a href="/cs/fp-error-propagation">舍入误差如何传播</a>：浮点已经会表示，现在跟踪每步舍入。CMOS 反相器更后才把判决做成电路。</p><h3 id="似然不是后验" tabindex="-1">似然不是后验 <a class="header-anchor" href="#似然不是后验" aria-label="Permalink to &quot;似然不是后验&quot;">​</a></h3><p>\\(P(\\text{数据}|\\text{假设})\\) 与 \\(P(\\text{假设}|\\text{数据})\\) 同名不同向。把阳性检出率当成患病率，是丢掉先验。<span class="marginnote">初学者容易把「灵敏度 90%」读成「阳性结果里 90% 是患者」——这正是混淆了 \\(P(\\text{阳性}|\\text{患病})\\) 与 \\(P(\\text{患病}|\\text{阳性})\\) 的方向：分母从「全体患者」换成了「全体阳性者」，先验就在这一步换分母时被悄悄丢掉了。</span>也不把条件独立写成「看起来没关系」：定义仍是乘积公式。</p><p><span class="marginnote">Rosen 用全概率与贝叶斯做有限求和。Shannon 的条件熵是条件分布上的 \\(H\\)。第一课的判决是确定性阈值；这里的条件是概率权重的再分配。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写出假设划分与观测。填似然 \\(P(\\text{观测}|\\text{假设})\\) 与先验，归一化得后验。链式法则 \\(P(A\\cap B\\cap C)=P(A)P(B|A)P(C|A\\cap B)\\) 用于拆联合，与<a href="/cs/mutual-information">联合熵</a>的链式同形、对象不同（一个是概率，一个是熵值）。</p>',13)),(n(),A(s,null,{default:e(()=>[o(i,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20PRIOR%5B%22%E5%85%88%E9%AA%8C%20P(B)%22%5D%20--%3E%20BAYES%5B%22%E8%B4%9D%E5%8F%B6%E6%96%AF%E5%8F%8D%E8%BD%AC%22%5D%0A%20%20LIK%5B%22%E4%BC%BC%E7%84%B6%20P(A%7CB)%22%5D%20--%3E%20BAYES%0A%20%20BAYES%20--%3E%20POST%5B%22%E5%90%8E%E9%AA%8C%20P(B%7CA)%22%5D%0A%20%20POST%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E8%88%8D%E5%85%A5%E8%AF%AF%E5%B7%AE%E4%BC%A0%E6%92%AD%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[E("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"后课比特翻转模型：\\(P(\\text{收}1|\\text{发}0)\\) 是信道；译码是后验最大或最近邻（几何课已给后一条）。哈希「给定槽看键」很少用贝叶斯；误阳检验常用。期望 \\(\\mathbb{E}[X]=\\mathbb{E}[\\mathbb{E}[X|Y]]\\)（全期望）是线性性在条件分布上的用法，本课点名，不把条件期望当新测度。",-1)),a[5]||(a[5]=t("p",null,[t("span",{class:"marginnote"},"分母的全概率加总可以类比成对账：想知道「阳性里多少是真患者」，就得把阳性从每条路进来的账都收齐（真患者检出 + 健康人误报）再相加。只算一条路，分母偏小、后验虚高——「忽视基础比率」的错误多半出在这里。")],-1)),(n(),A(s,null,{default:e(()=>[o(i,{id:"mermaid-45",class:"mermaid",graph:"flowchart%20TD%0A%20%20POP%5B%2210000%20%E4%BA%BA%E6%9D%A5%E6%A3%80%E6%B5%8B%22%5D%20--%3E%20SICK%5B%22%E7%9C%9F%E6%82%A3%E7%97%85%2010%20%E4%BA%BA%EF%BC%9A%E5%85%88%E9%AA%8C%200.1%25%22%5D%0A%20%20POP%20--%3E%20WELL%5B%22%E5%81%A5%E5%BA%B7%209990%20%E4%BA%BA%22%5D%0A%20%20SICK%20--%3E%20TP%5B%22%E6%A3%80%E5%87%BA%E9%98%B3%E6%80%A7%209%20%E4%BA%BA%EF%BC%9A%E7%81%B5%E6%95%8F%E5%BA%A6%2090%25%22%5D%0A%20%20WELL%20--%3E%20FP%5B%22%E8%AF%AF%E6%8A%A5%E9%98%B3%E6%80%A7%2099%20%E4%BA%BA%EF%BC%9A%E8%AF%AF%E6%8A%A5%E7%8E%87%201%25%22%5D%0A%20%20TP%20--%3E%20POSC%5B%22%E9%98%B3%E6%80%A7%E5%90%88%E8%AE%A1%20108%20%E4%BA%BA%22%5D%0A%20%20FP%20--%3E%20POSC%0A%20%20POSC%20--%3E%20POST%5B%22%E9%98%B3%E6%80%A7%E8%80%85%E7%9C%9F%E6%82%A3%E7%97%85%E6%A6%82%E7%8E%87%20%3D%209%20%C3%B7%20108%20%E2%89%88%208.3%25%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入连续密度、共轭先验、MCMC。大模型栏的 token 条件分布是另一张表，本栏不重写 Transformer。金融栏的测度换元不进来。</p><p>后课默认：有限对象上条件即限制后归一化；反转必须带先验。数值计算从下一课跟踪舍入开始；比特的物理实现更后才到反相器。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>条件是限制在观测上再归一化；贝叶斯反转似然与先验。</li><li>全概率把划分拆开；忽略基础比率会把似然当成后验。</li><li>信息与离散课结束；下一课跟踪浮点舍入如何传播。</li><li>出处：Rosen；Shannon, 1948。</li></ul>',5))])}const x=l(p,[["render",P]]);export{u as __pageData,x as default};
